package tn.esprit.partnerintelligence.entity;
import jakarta.persistence.*;import java.time.Instant;@Entity public class PromptTemplateVersion { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String promptKey; private String versionTag; @Column(columnDefinition="TEXT") private String templateText; private boolean active=true; private Instant createdAt=Instant.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getPromptKey(){return promptKey;} public void setPromptKey(String promptKey){this.promptKey=promptKey;} public String getVersionTag(){return versionTag;} public void setVersionTag(String versionTag){this.versionTag=versionTag;} public String getTemplateText(){return templateText;} public void setTemplateText(String templateText){this.templateText=templateText;} public boolean isActive(){return active;} public void setActive(boolean active){this.active=active;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant createdAt){this.createdAt=createdAt;} }